import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    自定义 AscendC ConvTranspose1d 内核调用（stride=1, padding=0, output_padding=0, groups=1, 无偏置）
    权重参数形状遵循 PyTorch: [in_channels, out_channels, kernel_size]
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        assert stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias is False, \
            "该自定义算子当前仅支持 stride=1, padding=0, output_padding=0, groups=1, bias=False"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        # PyTorch ConvTranspose1d 权重形状: [in_channels, out_channels, kernel_size]
        weight = torch.empty(in_channels, out_channels, kernel_size)
        # 采用与 PyTorch 类似的初始化策略
        torch.nn.init.kaiming_uniform_(weight, a=5 ** 0.5)
        self.weight = torch.nn.Parameter(weight)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_ops_lib.conv_transposed_1d_custom(x, self.weight)
